import{APIService}from"./api.js";export class DatabaseService{static async getStudents(){const e=await APIService.get("school/students");return e?Object.entries(e).map(([e,t])=>({id:e,...t})):[]}static async getStudent(e){return APIService.get(`school/students/${e}`)}static async saveStudent(e,t){return APIService.post(`school/students/${e}`,t)}static async updateStudent(e,t){return APIService.patch(`school/students/${e}`,t)}static async removeStudent(e){return APIService.delete(`school/students/${e}`)}static async getTeachers(){const e=await APIService.get("school/teachers");return e?Object.entries(e).map(([e,t])=>({id:e,...t})):[]}static async getTeacher(e){return APIService.get(`school/teachers/${e}`)}static async saveTeacher(e,t){return APIService.post(`school/teachers/${e}`,t)}static async updateTeacher(e,t){return APIService.patch(`school/teachers/${e}`,t)}static async removeTeacher(e){return APIService.delete(`school/teachers/${e}`)}static async saveLoginMapping(e,t){return APIService.post(`school/login_mappings/${e}`,t)}static async removeLoginMapping(e){return APIService.delete(`school/login_mappings/${e}`)}static async archiveStudent(e,t){return APIService.post(`school/archives/students/${e}`,t)}static async logStudentStatusHistory(e){const t="0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz";let s="";for(let e=0;e<16;e++)s+=t.charAt(Math.floor(62*Math.random()));return APIService.post(`school/student_status_history/${s}`,e)}static async getExamWindows(){const e=await APIService.get("school/exam_windows");return e?Object.entries(e).map(([e,t])=>({id:e,...t})):[]}static async saveExamWindow(e,t){return APIService.post(`school/exam_windows/${e}`,t)}static async updateExamStatus(e,t){return APIService.patch(`school/exam_windows/${e}`,{status:t})}static async removeExamWindow(e){return APIService.delete(`school/exam_windows/${e}`)}static async getDraftResults(){return APIService.get("school/draft_results")||{}}static async getStudentResults(e,t){return APIService.get(`school/results/${e}/${t}`)}static async saveDraftMark(e,t,s,c){return APIService.post(`school/draft_results/${e}/${t}/${s}`,c)}static async savePublishedMark(e,t,s,c){return APIService.post(`school/results/${e}/${t}/${s}`,c)}static async batchUpdate(e){return APIService.patch("",e)}static async getAttendance(e){return APIService.get(`school/attendance/${e}`)||{}}static async getClassConfigs(e){return APIService.get(`school/class_configs/${e}`)||{}}static async getPeriodTimings(){const e=await APIService.get("school/config/period_timings");return e?Object.entries(e).map(([e,t])=>({id:e,...t})):[]}static async savePeriodTiming(e,t){return APIService.post(`school/config/period_timings/${e}`,t)}static async removePeriodTiming(e){return APIService.delete(`school/config/period_timings/${e}`)}static async getNotices(){const e=await APIService.get("school/notices");return e?Object.entries(e).map(([e,t])=>({id:e,...t})):[]}static async saveNotice(e){const t="0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz";let s="";for(let e=0;e<16;e++)s+=t.charAt(Math.floor(62*Math.random()));return APIService.post(`school/notices/${s}`,e)}static async getTickets(){const e=await APIService.get("school/tickets");return e?Object.entries(e).map(([e,t])=>({id:e,...t})):[]}static async saveTicket(e,t){return APIService.post(`school/tickets/${e}`,t)}static async getSuggestions(){const e=await APIService.get("school/suggestions");return e?Object.entries(e).map(([e,t])=>({id:e,...t})):[]}static async saveSuggestion(e,t){return APIService.post(`school/suggestions/${e}`,t)}static async getClassChangeRequests(){const e=await APIService.get("school/class_change_requests");return e?Object.entries(e).map(([e,t])=>({id:e,...t})):[]}static async saveClassChangeRequest(e,t){return APIService.post(`school/class_change_requests/${e}`,t)}static async updateClassChangeRequestStatus(e,t){return APIService.patch(`school/class_change_requests/${e}`,{status:t})}}